const response = $json || {};
const batch = $('Encode Legal OCR Batch').item.json;
const payload = response.data && typeof response.data === 'object' && !Array.isArray(response.data)
  ? response.data
  : response;

const apiError = payload?.details?.description
  ?? response?.details?.description
  ?? payload?.error?.description
  ?? response?.error?.description
  ?? payload?.error?.message
  ?? payload?.error?.status
  ?? payload?.details?.message
  ?? response?.error?.message
  ?? response?.details?.message
  ?? (typeof payload?.error === 'string' ? payload.error : null);
if (apiError) {
  const httpCode = payload?.details?.httpCode ?? response?.details?.httpCode ?? payload?.statusCode ?? response?.statusCode ?? 'unknown';
  throw new Error(
    `OCR_BATCH_API_ERROR batch=${batch.batch_index + 1}/${batch.batch_count} ` +
    `pages=${batch.page_start ?? 'n/a'}-${batch.page_end ?? 'n/a'} ` +
    `http=${httpCode} ` +
    `message=${String(apiError).slice(0, 500)}`
  );
}

const candidates = Array.isArray(payload.candidates) ? payload.candidates : [];
const finishReasons = candidates.map(candidate => candidate?.finishReason ?? candidate?.finish_reason).filter(Boolean);
const incomplete = finishReasons.filter(reason => reason !== 'STOP');
